def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    recent = history[-10:] if n >= 10 else history
    recent_d = sum(1 for _, o in recent if o == 'D')
    total_d = sum(1 for _, o in history if o == 'D')
    total_c = n - total_d

    if total_c == 0:
        return 'D'

    if my_last == 'D' and opp_last == 'D':
        both_run = 0
        for m, o in reversed(history):
            if m == 'D' and o == 'D':
                both_run += 1
            else:
                break
        if both_run >= 3 and total_c >= total_d:
            return 'C'
        if total_c >= total_d and rng.random() < 0.3:
            return 'C'

    if recent_d >= 6:
        return 'D'
    if recent_d == 0:
        return 'C'
    if recent_d <= 2 and total_c > total_d:
        return 'C'
    if total_d >= total_c:
        return 'D'

    run = 0
    for _, o in reversed(history):
        if o == 'D':
            run += 1
        else:
            break

    if opp_last == 'D':
        if run == 1:
            return 'C'
        if my_last == 'D':
            return 'C' if rng.random() < 0.4 else 'D'
        return 'D'

    return 'C'
